private static IEnumerable<ImmutableList<TItem>> GenerateCombinations<TItem>(
    IList<IEnumerable<TItem>> enumerables, 
    int currentIndex, 
    ImmutableList<TItem> currentCombination) {

    // Base case: we've processed all dimensions
    if (currentIndex >= enumerables.Count) {
        yield return currentCombination;
        yield break;
    }

    // For each item in the current dimension
    foreach (var item in enumerables[currentIndex]) {
        // Recursively process the next dimension with this item added
        foreach (var combination in GenerateCombinations(
            enumerables, 
            currentIndex + 1, 
            currentCombination.Add(item))) {
            yield return combination;
        }
    }
}

