public static IEnumerable<ImmutableList<TItem>> CalcCombinationsOfOneFromEach<TItem>(
    IEnumerable<IEnumerable<TItem>> enumerables ) {
    if (enumerables == null)
        throw new ArgumentNullException(nameof(enumerables));

    var enumerableList = enumerables.ToList();

    // Handle empty outer input - yield one empty combination
    if (enumerableList.Count == 0) {
        yield return ImmutableList<TItem>.Empty;
        yield break;
    }

    // Check for any empty inner sequences and throw ArgumentException
    foreach (var enumerable in enumerableList) {
        if (enumerable == null)
            throw new ArgumentException("Inner sequence cannot be null");
        if (!enumerable.Any())
            throw new ArgumentException("Empty inner sequence not allowed");
    }

    // Use iterative approach to build combinations - this ensures proper lazy evaluation
    var stacks = new Stack<EnumeratorState<TItem>>[enumerableList.Count];
    for (int i = 0; i < enumerableList.Count; i++) {
        stacks[i] = new Stack<EnumeratorState<TItem>>();
        stacks[i].Push(new EnumeratorState<TItem>(enumerableList[i].GetEnumerator(), false));
    }

    var currentCombination = ImmutableList<TItem>.Empty;
    var indices = new int[enumerableList.Count];

    while (true) {
        // Try to advance the rightmost enumerator
        bool canAdvance = true;
        int pos = enumerableList.Count - 1;

        while (pos >= 0 && canAdvance) {
            var stack = stacks[pos];
            if (stack.Count > 0) {
                var state = stack.Peek();
                if (state.Enumerator.MoveNext()) {
                    // Successfully advanced
                    indices[pos] = state.Enumerator.Current;
                    break;
                } else {
                    // Can't advance, pop and try previous position
                    stack.Pop();
                    pos--;
                    if (pos >= 0) {
                        // Reset the next position
                        stacks[pos].Clear();
                        stacks[pos].Push(new EnumeratorState<TItem>(enumerableList[pos].GetEnumerator(), false));
                    }
                }
            } else {
                canAdvance = false;
                pos--;
            }
        }

        if (pos < 0) {
            // No more combinations
            break;
        }

        // Build current combination
        var combination = ImmutableList<TItem>.Empty;
        for (int i = 0; i < enumerableList.Count; i++) {
            combination = combination.Add(indices[i]);
        }
        yield return combination;
    }
}

