                        var newReference = $"<PackageReference Include=\"{targetInfo.Name}\" Version=\"{targetInfo.Version}\" />";
                        text = text.Replace(match.Value, newReference);
                    }
                }

                // Only write if there were changes
                if (text != originalText)
