            current = current.Add(items[indices[i]]);
        }
        yield return current;

        // Increment indices - this is the key part to get the right order
        int pos = enumerableList.Count - 1;
        while (pos >= 0) {
            indices[pos]++;
            if (indices[pos] < counts[pos]) {
